<script setup>defineProps({open:Boolean,title:String,description:String,busy:Boolean});defineEmits(['close','confirm'])</script><template><Teleport to="body"><div v-if="open" class="fixed inset-0 z-[100] flex items-end justify-center bg-ink/60 p-4 backdrop-blur-sm sm:items-center" role="dialog" aria-modal="true" :aria-label="title" @click.self="$emit('close')"><section class="lp-card w-full max-w-md p-6 shadow-2xl"><h2 class="text-xl font-bold">{{title}}</h2><p class="mt-3 text-sm leading-6 text-slate-600">{{description}}</p><div class="mt-6 flex justify-end gap-3"><button class="btn-secondary" :disabled="busy" @click="$emit('close')">Cancel</button><button class="btn-danger" :disabled="busy" @click="$emit('confirm')"><span v-if="busy" class="lp-spinner"></span>Confirm</button></div></section></div></Teleport></template>
